package com.smartbank.controller;
import com.smartbank.config.JwtService; import com.smartbank.entity.User; import com.smartbank.repository.UserRepository; import com.smartbank.service.BankingService; import com.smartbank.service.AccountSecurityService; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.Map;
@RestController @RequestMapping("/api/auth") public class AuthController {
 private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;private final BankingService banking;private final AccountSecurityService accountSecurity;
 public AuthController(UserRepository u,PasswordEncoder e,JwtService j,BankingService b,AccountSecurityService s){users=u;encoder=e;jwt=j;banking=b;accountSecurity=s;}
 public record Register(@NotBlank @Size(max=120) String fullName,@Email @NotBlank String email,@NotBlank @Size(max=30) String phone,@NotBlank @Pattern(regexp="^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d).{8,72}$",message="Use 8+ characters with uppercase, lowercase, and a number.") String password){}
 public record Login(@Email @NotBlank String email,@NotBlank String password){}
 public record Forgot(@Email @NotBlank String email){}
 public record Reset(@NotBlank String token,@NotBlank @Pattern(regexp="^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d).{8,72}$",message="Use 8+ characters with uppercase, lowercase, and a number.") String newPassword){}
 @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> register(@Valid @RequestBody Register r){if(users.existsByEmailIgnoreCase(r.email()))throw new ResponseStatusException(HttpStatus.CONFLICT,"An account with this email already exists.");User u=new User();u.fullName=r.fullName().trim();u.email=r.email().trim().toLowerCase();u.phone=r.phone().trim();u.passwordHash=encoder.encode(r.password());u.role="CUSTOMER";banking.register(u);return loginResponse(u);}
 @PostMapping("/login") public Map<String,Object> login(@Valid @RequestBody Login r){User u=users.findByEmailIgnoreCase(r.email()).filter(x->x.active&&encoder.matches(r.password(),x.passwordHash)).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Email or password is incorrect."));return loginResponse(u);}
 @PostMapping("/forgot-password") @ResponseStatus(HttpStatus.ACCEPTED) public Map<String,String> forgot(@Valid @RequestBody Forgot r){accountSecurity.requestReset(r.email());return Map.of("message","If the account exists and email delivery is configured, password reset instructions will arrive shortly.");}
 @PostMapping("/reset-password") public Map<String,String> reset(@Valid @RequestBody Reset r){accountSecurity.reset(r.token(),r.newPassword());return Map.of("message","Password updated. You can now sign in.");}
 private Map<String,Object> loginResponse(User u){return Map.of("token",jwt.create(u.email,u.role),"user",Map.of("id",u.id,"name",u.fullName,"email",u.email,"phone",u.phone,"role",u.role));}
}
